from pathlib import Path

path=Path('market-edge-lab/real/baseline/founder-terminal.html')
text=path.read_text(encoding='utf-8')

CSS='''\n/* ADVISOR STATUS PANEL — read-only cockpit visibility */\n.advisorPanel{display:grid;grid-template-columns:1.05fr 1fr 1fr 1.2fr 1.2fr 1.6fr;border-bottom:1px solid var(--line);background:#071019}\n.advisorCell{padding:7px 10px;border-right:1px solid var(--line);min-width:0}\n.advisorCell:last-child{border-right:0}.advisorTitle{font-size:9px;letter-spacing:.12em;font-weight:900;color:var(--gold)}\n.advisorBig{font-size:11px;font-weight:900;color:#e9f2fb;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.advisorSub{font-size:8px;color:var(--muted);margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.advisorGood{color:var(--green)}.advisorWarn{color:var(--amber)}.advisorBad{color:var(--red)}\n@media(max-width:900px){.advisorPanel{grid-template-columns:repeat(3,1fr)}}\n@media(max-width:520px){.advisorPanel{grid-template-columns:repeat(2,1fr)}.advisorCell{padding:6px}}\n'''

PANEL='''\n<section class="advisorPanel" id="advisorPanel" aria-live="polite">\n  <div class="advisorCell"><div class="advisorTitle">15-MIN ADVISOR</div><div id="advisorStatus" class="advisorBig advisorWarn">CHECKING…</div><div id="advisorUpdated" class="advisorSub">UPDATED —</div></div>\n  <div class="advisorCell"><div class="lab">MARKET</div><div id="advisorMarket" class="advisorBig">—</div><div id="advisorBreadth" class="advisorSub">BREADTH —</div></div>\n  <div class="advisorCell"><div class="lab">TOP BULLISH</div><div id="advisorBull" class="advisorBig">—</div><div id="advisorBullSub" class="advisorSub">—</div></div>\n  <div class="advisorCell"><div class="lab">TOP BEARISH</div><div id="advisorBear" class="advisorBig">—</div><div id="advisorBearSub" class="advisorSub">—</div></div>\n  <div class="advisorCell"><div class="lab">WATCH</div><div id="advisorWatch" class="advisorBig">—</div><div id="advisorPartial" class="advisorSub">PARTIAL —</div></div>\n  <div class="advisorCell"><div class="lab">AUTHORITY</div><div class="advisorBig advisorGood">READ ONLY</div><div class="advisorSub">NO SCORE · NO EXECUTION · NO ARM/DISARM</div></div>\n</section>\n'''

JS='''\n<script>\n(()=>{\n  const ADVISOR_BRIDGE='https://market-edge-advisor-bridge.darkbishop43.workers.dev/advisor-current';\n  let advisorState=null;\n  const byId=id=>document.getElementById(id);\n  const ageText=s=>{if(!Number.isFinite(Number(s)))return 'age unavailable';const n=Math.max(0,Math.floor(Number(s)));if(n<60)return n+'s ago';if(n<3600)return Math.floor(n/60)+'m ago';return Math.floor(n/3600)+'h ago';};\n  const itemName=x=>typeof x==='string'?x:String(x?.asset||x?.symbol||x?.name||'').trim();\n  const findAssessment=(state,asset)=>Array.isArray(state?.assetAssessments)?state.assetAssessments.find(x=>String(x?.asset||'')===asset):null;\n  const describe=(state,list)=>{const names=(Array.isArray(list)?list:[]).slice(0,3).map(itemName).filter(Boolean);return {names:names.join(' · ')||'NONE',sub:names.map(a=>{const x=findAssessment(state,a);return x?`${a} ${x.advisoryConfidence||'LOW'} ${x.setupPhase||''}`.trim():a;}).join(' · ')||'—'};};\n  const breadthText=b=>{if(!b)return 'BREADTH —';const up=Number(b.numberAssetsBullish??b.up??0),down=Number(b.numberAssetsBearish??b.down??0),mixed=Number(b.numberAssetsMixed??b.mixed??0);if([up,down,mixed].some(Number.isFinite))return `${up||0} ↑ / ${down||0} ↓ / ${mixed||0} mixed`;const upPct=Number(b.marketBreadthUpPct),downPct=Number(b.marketBreadthDownPct);if(Number.isFinite(upPct)||Number.isFinite(downPct))return `${Number.isFinite(upPct)?upPct.toFixed(0):'—'}% ↑ / ${Number.isFinite(downPct)?downPct.toFixed(0):'—'}% ↓`;return 'BREADTH —';};\n  function paintUnavailable(){advisorState=null;const s=byId('advisorStatus');if(s){s.textContent='UNAVAILABLE';s.className='advisorBig advisorBad';}byId('advisorUpdated').textContent='UPDATED —';byId('advisorMarket').textContent='UNKNOWN';byId('advisorBreadth').textContent='BREADTH —';byId('advisorBull').textContent='—';byId('advisorBullSub').textContent='—';byId('advisorBear').textContent='—';byId('advisorBearSub').textContent='—';byId('advisorWatch').textContent='ADVISOR STATE UNAVAILABLE';byId('advisorPartial').textContent='PARTIAL —';}\n  function paint(state){advisorState=state;const status=String(state?.status||'UNAVAILABLE');const s=byId('advisorStatus');s.textContent=status;s.className='advisorBig '+(status==='ACTIVE'?'advisorGood':status==='STALE'?'advisorWarn':'advisorBad');byId('advisorUpdated').textContent=(state?.generatedAt?new Date(state.generatedAt).toLocaleString():'UPDATED —')+(Number.isFinite(Number(state?.ageSeconds))?' · '+ageText(state.ageSeconds):'');byId('advisorMarket').textContent=state?.marketRegime||'UNKNOWN';byId('advisorBreadth').textContent=breadthText(state?.marketBreadth);const bull=describe(state,state?.strongestBullishContext);byId('advisorBull').textContent=bull.names;byId('advisorBullSub').textContent=bull.sub;const bear=describe(state,state?.strongestBearishContext);byId('advisorBear').textContent=bear.names;byId('advisorBearSub').textContent=bear.sub;const risks=(Array.isArray(state?.marketRiskFlags)?state.marketRiskFlags:[]).map(String);const divs=(Array.isArray(state?.largestDivergences)?state.largestDivergences:[]).map(itemName).filter(Boolean);byId('advisorWatch').textContent=(risks[0]||divs[0]||'NO MAJOR WARNING');const partial=(Array.isArray(state?.assetAssessments)?state.assetAssessments:[]).filter(x=>x?.dataStatus==='PARTIAL').map(x=>x.asset);byId('advisorPartial').textContent=partial.length?'PARTIAL '+partial.join(' · '):'PARTIAL NONE';}\n  async function refreshAdvisor(){try{const r=await fetch(ADVISOR_BRIDGE,{method:'GET',cache:'no-store',credentials:'omit'});const j=await r.json();if(!r.ok||!j||j.status==='UNAVAILABLE')return paintUnavailable();paint(j);}catch{paintUnavailable();}}\n  function tickAge(){if(!advisorState?.generatedAt)return;const ms=Date.parse(advisorState.generatedAt);if(!Number.isFinite(ms))return;const age=Math.max(0,Math.floor((Date.now()-ms)/1000));advisorState.ageSeconds=age;byId('advisorUpdated').textContent=new Date(ms).toLocaleString()+' · '+ageText(age);if(age>720&&advisorState.status==='ACTIVE'){advisorState.status='STALE';const s=byId('advisorStatus');s.textContent='STALE';s.className='advisorBig advisorWarn';}}\n  refreshAdvisor();setInterval(refreshAdvisor,30000);setInterval(tickAge,1000);\n})();\n</script>\n'''

if 'ADVISOR STATUS PANEL — read-only cockpit visibility' not in text:
    if '</style>' not in text: raise SystemExit('STYLE_ANCHOR_NOT_FOUND')
    text=text.replace('</style>',CSS+'</style>',1)
if 'id="advisorPanel"' not in text:
    anchor='<main class="workspace">'
    if anchor not in text: raise SystemExit('MAIN_ANCHOR_NOT_FOUND')
    text=text.replace(anchor,PANEL+'\n'+anchor,1)
if "const ADVISOR_BRIDGE='https://market-edge-advisor-bridge.darkbishop43.workers.dev/advisor-current'" not in text:
    if '</body>' not in text: raise SystemExit('BODY_ANCHOR_NOT_FOUND')
    text=text.replace('</body>',JS+'</body>',1)

path.write_text(text,encoding='utf-8')
print('COCKPIT_ADVISOR_PANEL_PATCHED=YES')
